def run(cmd):
    p = subprocess.run(cmd, cwd=ROOT, capture_output=True, text=True)
    if p.returncode != 0:
        raise RuntimeError(
            "Kommando misslyckades:\n"
            + " ".join(map(str, cmd))
            + "\n\nSTDOUT:\n" + p.stdout
            + "\nSTDERR:\n" + p.stderr
        )
    return p

def write_assets(test_mode):
    dirname = TEST_ASSET_DIRNAME if test_mode else LIVE_ASSET_DIRNAME
    target = ROOT / "assets" / "icons" / dirname
    target.mkdir(parents=True, exist_ok=True)

    for filename, encoded in PAYLOAD.items():
        if filename == GOALIE_FILE:
            continue
        (target / filename).write_bytes(base64.b64decode(encoded))

    # Test goalie gets its own directory so live Sport asset remains untouched.
    if test_mode:
        goalie_dir = ROOT / "assets" / "icons" / "runtmigo_goalie_v2_4_3_test"
        goalie_dir.mkdir(parents=True, exist_ok=True)
        (goalie_dir / GOALIE_FILE).write_bytes(
            base64.b64decode(PAYLOAD[GOALIE_FILE])
        )

    return dirname

def img(dirname, filename):
    # Intentionally use the exact same CSS classes as working Sport V2.1.
    return (
        '\'<img class="runtmigo-glossy-pin runtmigo-sport-glossy-pin" '
        + 'src="../assets/icons/' + dirname + '/' + filename + '" '
        + 'alt="" '
        + 'style="width:28px;height:34px;object-fit:contain;display:block;margin:auto;" />\''
    )

def object_bounds(text, const_name):
    m = re.search(
        r"const\s+" + re.escape(const_name)
        + r"\s*=\s*(?P<open>\{\{|\{)",
        text,
    )
    if not m:
        raise RuntimeError("STOP: hittar inte " + const_name)

    start = m.end()
    # Object uses doubled braces in build_map.py and normal braces in generated HTML.
    close_pat = r"\}\}\s*;" if m.group("open") == "{{" else r"\}\s*;"
    close = re.search(close_pat, text[start:])
    if not close:
        raise RuntimeError("STOP: hittar inte slutet på " + const_name)

    return start, start + close.start()

def patch_subcategory_symbols(text, dirname):
    start, end = object_bounds(text, "SUBCATEGORY_SYMBOLS")
    body = text[start:end]

    line_re = re.compile(
        r'^(?P<indent>\s*)"(?P<key>[^"]+)"\s*:\s*(?P<value>.+?)(?P<comma>,?)(?P<trail>\s*)$',
        re.M,
    )

    changed = []
    fallback = []
    existing_keys = set()

    def repl(m):
        key = m.group("key")
        existing_keys.add(key)

        if "|" not in key:
            return m.group(0)

        category, sub = key.split("|", 1)
        if category not in NON_SPORT:
            return m.group(0)

        filename = EXACT.get(key) or MAIN[category]

        if key in EXACT:
            changed.append(key)
        else:
            fallback.append(key)

        return (
            m.group("indent")
            + '"' + key + '": '
            + img(dirname, filename)
            + m.group("comma")
            + m.group("trail")
        )

    patched_body = line_re.sub(repl, body)

    # V2.2: add mappings that do not exist in the old object at all.
    # This is especially important for Motor & fordon and Häst & ridsport.
    missing = [
        key for key in EXACT
        if key not in existing_keys
    ]

    if missing:
        # Ensure previous last property ends with comma before appending.
        stripped = patched_body.rstrip()
        if stripped and not stripped.endswith(","):
            # Add comma to the last property line only.
            lines = stripped.splitlines()
            for i in range(len(lines) - 1, -1, -1):
                if ":" in lines[i] and '"' in lines[i]:
                    lines[i] = lines[i].rstrip() + ","
                    break
            patched_body = "\n".join(lines) + "\n"
        elif not patched_body.endswith("\n"):
            patched_body += "\n"

        for key in missing:
            category = key.split("|", 1)[0]
            if category not in NON_SPORT:
                continue
            patched_body += (
                '    "' + key + '": '
                + img(dirname, EXACT[key])
                + ",\n"
            )

    if not changed and not fallback and not missing:
        raise RuntimeError(
            "STOP: inga aktiva icke-Sport-symboler hittades eller behövde läggas till."
        )

    return (
        text[:start] + patched_body + text[end:],
        changed,
        fallback,
        missing,
    )


def patch_category_symbols(text, dirname):
    start, end = object_bounds(text, "CATEGORY_SYMBOLS")
    body = text[start:end]

    line_re = re.compile(
        r'^(?P<indent>\s*)"(?P<key>[^"]+)"\s*:\s*(?P<value>.+?)(?P<comma>,?)(?P<trail>\s*)$',
        re.M,
    )

    changed = []
    existing = set()

    def repl(m):
        key = m.group("key")
        existing.add(key)

        if key not in MAIN:
            return m.group(0)

        changed.append(key)
        return (
            m.group("indent")
            + '"' + key + '": '
            + img(dirname, MAIN[key])
            + m.group("comma")
            + m.group("trail")
        )

    patched_body = line_re.sub(repl, body)

    missing_main = [
        category for category in MAIN
        if category not in existing
    ]

    if missing_main:
        stripped = patched_body.rstrip()
        if stripped and not stripped.endswith(","):
            lines = stripped.splitlines()
            for i in range(len(lines) - 1, -1, -1):
                if ":" in lines[i] and '"' in lines[i]:
                    lines[i] = lines[i].rstrip() + ","
                    break
            patched_body = "\n".join(lines) + "\n"
        elif not patched_body.endswith("\n"):
            patched_body += "\n"

        for category in missing_main:
            patched_body += (
                '    "' + category + '": '
                + img(dirname, MAIN[category])
                + ",\n"
            )

    return (
        text[:start] + patched_body + text[end:],
        changed + missing_main,
    )


def force_gray(text):
    start, end = object_bounds(text, "CATEGORY_COLORS")
    body = text[start:end]
    pat = r'("Övrigt"\s*:\s*")([^"]+)(")'
    matches = list(re.finditer(pat, body))
    if len(matches) != 1:
        raise RuntimeError(
            "STOP: Övrigt-färgen är inte entydig i CATEGORY_COLORS."
        )
    body = re.sub(pat, r"\1#757575\3", body, count=1)
    return text[:start] + body + text[end:]

def patch_goalie_test(text):
    old = (
        "../assets/icons/"
        + SPORT_DIR
        + "/"
        + GOALIE_FILE
    )
    new = (
        "../assets/icons/runtmigo_goalie_v2_4_3_test/"
        + GOALIE_FILE
    )
    if old not in text:
        raise RuntimeError("STOP: hittar inte aktiva Ishockey-referensen.")
    return text.replace(old, new)

def make_test_source(text):
    if "eventfinder_map.html" not in text:
        raise RuntimeError("STOP: hittar inte eventfinder_map.html.")
    out = text.replace(
        "eventfinder_map.html",
        "eventfinder_map_glossy_repair_v2_4_3_test.html",
    )
    if "eventfinder_map.html" in out:
        raise RuntimeError("STOP: testoutput kunde inte isoleras.")
    return out


def patch_multi_category_glossy(text):
    marker = "RUNTMIGO_MULTI_CATEGORY_GLOSSY_V2_4_3"

    # Idempotent.
    if marker in text:
        return text, False

    pattern = r'(?P<indent>\s*)let\s+markerSymbol\s*=\s*"◆"\s*;'
    matches = list(re.finditer(pattern, text))

    if len(matches) != 1:
        raise RuntimeError(
            'STOP: förväntade exakt en markerSymbol-default "◆", hittade '
            + str(len(matches))
        )

    replacement = (
        matches[0].group("indent")
        + "/* " + marker + " */\n"
        + matches[0].group("indent")
        + 'let markerSymbol = categorySymbol("Övrigt");'
    )

    patched = re.sub(
        pattern,
        replacement,
        text,
        count=1,
    )

    return patched, True



def patch_glossy_pin_as_full_marker(text):
    marker = "RUNTMIGO_GLOSSY_PIN_AS_FULL_MARKER_V2_4_3"

    if marker in text:
        return text, False

    style_end = text.find("</style>")
    if style_end < 0:
        raise RuntimeError("STOP: hittar inte </style>.")

    css = """
        /* RUNTMIGO_GLOSSY_PIN_AS_FULL_MARKER_V2_4_3 */
        .arena-marker:has(.runtmigo-glossy-pin)::before,
        .arena-marker:has(.runtmigo-glossy-pin)::after {{
            display: none !important;
            content: none !important;
        }}

        .arena-marker:has(.runtmigo-glossy-pin)
        .arena-marker-symbol {{
            overflow: visible !important;
        }}
"""

    return text[:style_end] + css + "\n" + text[style_end:], True


def validate(original, patched):
    if original.count("L.divIcon") != patched.count("L.divIcon"):
        raise RuntimeError("STOP: L.divIcon ändrades.")

    # Multi-category marker must use the glossy neutral category pin,
    # never the old flat diamond.
    if 'RUNTMIGO_MULTI_CATEGORY_GLOSSY_V2_4_3' not in patched:
        raise RuntimeError(
            "STOP: multi-category glossy patch saknas."
        )

    if 'let markerSymbol = "◆";' in patched:
        raise RuntimeError(
            "STOP: gamla platta multi-category-symbolen ◆ finns kvar."
        )

    if "RUNTMIGO_GLOSSY_PIN_AS_FULL_MARKER_V2_4_3" not in patched:
        raise RuntimeError(
            "STOP: CSS för glossy PNG som hel kartnål saknas."
        )

    for selector in (
        ".arena-marker:has(.runtmigo-glossy-pin)::before",
        ".arena-marker:has(.runtmigo-glossy-pin)::after",
    ):
        if selector not in patched:
            raise RuntimeError(
                "STOP: saknar glossy-marker-selector: " + selector
            )

    # Sport V2.1 architecture must remain.
    for marker in (
        "RUNTMIGO_SPORT_GLOSSY_SIZE_V2_1",
        "RUNTMIGO_SPORT_GLOSSY_PNGS_V2_1",
        "RUNTMIGO_SPORT_GLOSSY_PNGS_V2_1_RETURN",
    ):
        if marker not in patched:
            raise RuntimeError("STOP: Sport V2.1 saknas: " + marker)

    # Every non-Sport value still present in the two active symbol objects
    # must now be a glossy img using the same class as Sport.
    s1, e1 = object_bounds(patched, "SUBCATEGORY_SYMBOLS")
    body = patched[s1:e1]
    for category in NON_SPORT:
        for line in body.splitlines():
            if '"' + category + "|" not in line:
                continue
            if "runtmigo-sport-glossy-pin" not in line:
                raise RuntimeError(
                    "STOP: gammal symbol återstår: " + line.strip()
                )

    # V2.2: every exact Motor/Horse mapping must exist in the active object.
    for prefix in ("Motor & fordon|", "Häst & ridsport|"):
        expected = [key for key in EXACT if key.startswith(prefix)]
        for key in expected:
            matches = [
                line for line in body.splitlines()
                if '"' + key + '"' in line
            ]
            if len(matches) != 1:
                raise RuntimeError(
                    "STOP: saknad/duplicerad aktiv glossy-rad: " + key
                )
            if "runtmigo-sport-glossy-pin" not in matches[0]:
                raise RuntimeError(
                    "STOP: Motor/Häst-rad är inte glossy: " + key
                )

    s2, e2 = object_bounds(patched, "CATEGORY_SYMBOLS")
    body2 = patched[s2:e2]
    for category in MAIN:
        matches = [
            line for line in body2.splitlines()
            if '"' + category + '"' in line
        ]
        if matches and not all(
            "runtmigo-sport-glossy-pin" in x
            for x in matches
        ):
            raise RuntimeError(
                "STOP: gammal huvudsymbol återstår för " + category
            )

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()

    original = BUILD.read_text(encoding="utf-8", errors="replace")
    dirname = write_assets(test_mode=not args.apply)

    patched, exact_changed, fallbacks, missing_added = patch_subcategory_symbols(
        original,
        dirname,
    )
    patched, main_changed = patch_category_symbols(
        patched,
        dirname,
    )
    patched = force_gray(patched)
    patched, multi_category_changed = patch_multi_category_glossy(patched)
    patched, full_marker_changed = patch_glossy_pin_as_full_marker(patched)

    validate(original, patched)

    print("=" * 92)
    print("RUNTMIGO – GLOSSY REPAIR V2.4.3")
    print("=" * 92)
    print("Läge:", "APPLY" if args.apply else "SEPARAT TESTBUILD")
    print("Metod: ersätter värden direkt i aktiva SUBCATEGORY_SYMBOLS/CATEGORY_SYMBOLS")
    print("Sport V2.1 ändras i build_map.py: NEJ")
    print("Icke-Sport exakta glossy-symboler:", len(exact_changed))
    print("Icke-Sport fallback till glossy huvudpin:", len(fallbacks))
    print("Saknade mappningar tillagda:", len(missing_added))
    print("Motor-mappningar tillagda:", len([x for x in missing_added if x.startswith('Motor & fordon|')]))
    print("Häst-mappningar tillagda:", len([x for x in missing_added if x.startswith('Häst & ridsport|')]))
    print("Glossy huvudkategorier ersatta:", len(main_changed))
    print("Flera kategorier på samma plats -> grå glossy pin:", "JA" if multi_category_changed else "REDAN FIXAT")
    print("Gamla platta nålen bakom glossy PNG döljs:", "JA" if full_marker_changed else "REDAN FIXAT")
    print("Ishockey synliga footprint = Fotboll exakt: JA")
    print("Övrigt färg: #757575")
    print("Samma CSS-klass som Sport: JA")
    print("L.divIcon ändras: NEJ")
    print("events.json ändras: NEJ")
    print("venue_catalog.json ändras: NEJ")

    if not args.apply:
        test_source = patch_goalie_test(patched)
        test_source = make_test_source(test_source)

        if TEST_BUILD.exists():
            TEST_BUILD.unlink()

        try:
            TEST_BUILD.write_text(test_source, encoding="utf-8")
            run(["python3", "-m", "py_compile", str(TEST_BUILD)])
            result = run(["python3", str(TEST_BUILD)])

            if not TEST_HTML.exists():
                raise RuntimeError("STOP: testsidan skapades inte.")

            print()
            print("TESTBUILD KLAR – PRODUKTIONEN ÄR ORÖRD")
            print("Öppna:")
            print(
                "http://localhost:8000/output/"
                "eventfinder_map_glossy_repair_v2_4_3_test.html"
            )

            if result.stdout.strip():
                print()
                print(result.stdout[-2500:])

        finally:
            if TEST_BUILD.exists():
                TEST_BUILD.unlink()

        return 0

    stamp = datetime.now().strftime("%Y_%m_%d_%H%M%S")
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)

    build_backup = BACKUP_DIR / (
        "build_map.py.before_glossy_repair_v2_4_3_" + stamp
    )
    shutil.copy2(BUILD, build_backup)

    sport_goalie = (
        ROOT / "assets" / "icons"
        / SPORT_DIR
        / GOALIE_FILE
    )
    if not sport_goalie.exists():
        raise RuntimeError(
            "STOP: aktiva Sport/Ishockey-PNG:n saknas: "
            + str(sport_goalie)
        )

    goalie_backup = BACKUP_DIR / (
        "sport__ishockey.png.before_goalie_v2_4_3_" + stamp
    )
    shutil.copy2(sport_goalie, goalie_backup)

    try:
        BUILD.write_text(patched, encoding="utf-8")

        # Only one Sport asset changes: Ishockey.
        sport_goalie.write_bytes(
            base64.b64decode(PAYLOAD[GOALIE_FILE])
        )

        run(["python3", "-m", "py_compile", "src/build_map.py"])
        result = run(["python3", "src/build_map.py"])

        if not PROD_HTML.exists():
            raise RuntimeError("STOP: produktionskartan skapades inte.")

    except Exception:
        shutil.copy2(build_backup, BUILD)
        shutil.copy2(goalie_backup, sport_goalie)
        try:
            run(["python3", "src/build_map.py"])
        except Exception:
            pass
        raise

    print()
    print("=" * 92)
    print("GLOSSY REPAIR V2.4.3 – APPLY KLART")
    print("=" * 92)
    print("Sport V2.1 bevarad: JA")
    print("Ishockey målvaktsmask: JA")
    print("Övriga aktiva symboler glossy: JA")
    print("Multi-category-markörer glossy: JA")
    print("Glossy PNG är själva kartnålen: JA")
    print("Övrigt grå glossy: JA")
    print("events.json ändrad: NEJ")
    print("venue_catalog.json ändrad: NEJ")
    print("Backup build_map:", build_backup)
    print("Backup Ishockey:", goalie_backup)

    if result.stdout.strip():
        print()
        print(result.stdout)

    return 0

if __name__ == "__main__":
    raise SystemExit(main())
